import React, { useState } from 'react';
import axios from 'axios';
import { Loader2, Upload, BrainCircuit, Eye, CircuitBoard } from 'lucide-react';
import PCBViewer from './PCBViewer';

export default function App() {
  const [file, setFile] = useState(null);
  const [loading, setLoading] = useState(false);
  const [status, setStatus] = useState("");
  const [aiSuggestions, setAiSuggestions] = useState(null);
  const [vizData, setVizData] = useState(null);

  const handleUpload = async () => {
    if (!file) return;
    setLoading(true); setStatus("Initializing AI..."); setAiSuggestions(null); setVizData(null);
    const formData = new FormData(); formData.append("file", file);
    try {
      const res = await axios.post("http://localhost:8000/process-pcb", formData);
      setAiSuggestions(res.data.ai_suggestions);
      setVizData(res.data.visualization);
      
      const bin = window.atob(res.data.file_data);
      const bytes = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
      const url = window.URL.createObjectURL(new Blob([bytes], { type: "application/zip" }));
      const link = document.createElement('a'); link.href = url; link.setAttribute('download', res.data.filename);
      document.body.appendChild(link); link.click();
      setStatus("Complete!");
    } catch (e) { console.error(e); setStatus("Error processing board."); } 
    finally { setLoading(false); }
  };

  return (
    <div className="min-h-screen bg-slate-950 text-white p-6 flex flex-col items-center">
      <div className="w-full max-w-6xl flex items-center gap-3 mb-8">
        <CircuitBoard className="text-blue-500 w-10 h-10" />
        <h1 className="text-3xl font-bold bg-gradient-to-r from-blue-400 to-emerald-400 bg-clip-text text-transparent">AI PCB Router</h1>
      </div>

      <div className="w-full max-w-6xl grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="space-y-6 lg:col-span-1">
          <div className="bg-slate-900 rounded-xl p-6 border border-slate-800 shadow-xl">
             <div className="border-2 border-dashed border-slate-700 rounded-lg p-6 text-center relative mb-4 hover:border-blue-500 transition-colors">
                <input type="file" accept=".kicad_pcb" onChange={(e)=>setFile(e.target.files[0])} className="absolute inset-0 w-full h-full opacity-0 cursor-pointer" />
                <div className="flex flex-col items-center gap-2">
                    <Upload className="text-slate-400"/>
                    <p className="text-sm text-slate-300">{file ? file.name : "Drop .kicad_pcb"}</p>
                </div>
             </div>
             <button onClick={handleUpload} disabled={!file || loading} className={`w-full py-3 rounded-lg font-bold flex items-center justify-center gap-2 ${loading ? 'bg-slate-800 text-slate-500' : 'bg-blue-600 hover:bg-blue-500'}`}>
                {loading ? <Loader2 className="animate-spin" /> : <BrainCircuit />} {loading ? "Processing..." : "Run Auto-Router"}
             </button>
             {status && <p className="text-center text-xs mt-3 text-emerald-400">{status}</p>}
          </div>

          {aiSuggestions && (
            <div className="bg-slate-900 rounded-xl p-6 border border-slate-800 shadow-xl h-[400px] flex flex-col">
               <h2 className="text-lg font-semibold text-emerald-400 mb-4 flex items-center gap-2"><BrainCircuit className="w-5 h-5"/> AI Net Strategy</h2>
               <div className="overflow-y-auto pr-2 space-y-3 custom-scrollbar flex-1">
                  {Object.entries(aiSuggestions.netclasses || {}).map(([name, rules]) => (
                    <div key={name} className="bg-slate-800 p-3 rounded border border-slate-700">
                      <div className="flex justify-between mb-1"><span className="font-bold text-slate-200">{name}</span><span className="text-xs bg-slate-700 px-2 py-0.5 rounded text-blue-300">W: {rules.trace_width}mm</span></div>
                      <div className="text-xs text-slate-500">Via: {rules.via_size}mm | Clr: {rules.clearance}mm</div>
                    </div>
                  ))}
               </div>
            </div>
          )}
        </div>

        <div className="lg:col-span-2 h-[600px] bg-slate-900 rounded-xl border border-slate-800 shadow-xl relative overflow-hidden">
          <div className="absolute top-4 left-4 z-10 bg-slate-900/80 backdrop-blur px-3 py-1 rounded-full border border-slate-700 flex items-center gap-2">
            <Eye className="w-4 h-4 text-blue-400" /><span className="text-xs font-semibold text-slate-300">Live Preview</span>
          </div>
          <div className="absolute bottom-4 right-4 z-10 flex gap-4 text-xs font-bold bg-slate-900/80 p-2 rounded border border-slate-700">
             <div className="flex items-center gap-1"><div className="w-3 h-3 rounded-full bg-red-500"></div> Top</div>
             <div className="flex items-center gap-1"><div className="w-3 h-3 rounded-full bg-blue-500"></div> Bottom</div>
             <div className="flex items-center gap-1"><div className="w-3 h-3 rounded-full bg-amber-400"></div> Pads</div>
          </div>
          {vizData ? <PCBViewer data={vizData} /> : <div className="w-full h-full flex items-center justify-center text-slate-600"><CircuitBoard className="w-16 h-16 opacity-20"/></div>}
        </div>
      </div>
    </div>
  );
}
